import { useState, useRef, useEffect, useCallback, useMemo } from 'react'
import { fetchJson, uploadFile } from '../../api'
import { hugpyFetch } from '../../runtime/config'
import './ChatPanel.css'

const PLACEHOLDER_CMDS = '/system <text> · /clear · /tokens <N>'

function isVLModel(model) {
  if (!model) return false
  // Capability lives in the FULL tasks list — primary_task alone hid vision
  // on models whose primary is e.g. text-generation.
  if (Array.isArray(model.tasks) && model.tasks.includes('image-text-to-text')) return true
  const task = model.primary_task || model.task
  return task === 'image-text-to-text'
}

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const r = new FileReader()
    r.onload = () => resolve(r.result)
    r.onerror = () => reject(r.error)
    r.readAsDataURL(file)
  })
}

function stripDataUrl(dataUrl) {
  const i = dataUrl.indexOf(',')
  return i >= 0 ? dataUrl.slice(i + 1) : dataUrl
}

export default function ChatPanel({ modelKey, model, onClose, messages = [], setMessages, chats = {}, models = [], onSwitchChat }) {
  // `messages`/`setMessages` are lifted to App (per-model, localStorage-backed)
  // so the conversation survives tab/route changes and reloads. setMessages
  // accepts the same value-or-updater shape as a useState setter.
  //
  // `chats` is that SAME per-model store useChats persists — the whole
  // { [modelKey]: Message[] } map — handed down so the top-right conversation
  // switcher can list every populated thread. It's read-only here and shares one
  // source of truth with `messages`: no separate state to drift. `onSwitchChat`
  // is App's own chat-opener (setActiveChat), so picking a model behaves exactly
  // like opening it from the model list. `models` is only for display names.
  const [input, setInput]           = useState('')
  const [system, setSystem]         = useState('')
  const [maxTokens, setMaxTokens]   = useState(null)   // null = model max (auto-continued)
  const [streaming, setStreaming]   = useState(false)
  const [attachment, setAttachment] = useState(null)   // {name, isImage, dataUrl?, path?, uploading?}
  const [allocation, setAllocation] = useState(null)   // {servedBy:'worker'|'local', workerId, workerName} — last dispatch
  const bottomRef = useRef(null)
  const inputRef  = useRef(null)
  const fileRef   = useRef(null)
  const abortRef  = useRef(null)   // AbortController for the in-flight stream
  const reqIdRef  = useRef(null)   // request_id of the in-flight stream (for cancel)

  const vlCapable = isVLModel(model)

  // Options for the top-right conversation switcher, read straight off the shared
  // `chats` store (no derived state to keep in sync). Every model with a
  // non-empty saved thread is offered, PLUS the model open right now even if its
  // thread is still empty — so the switcher always shows where you are and the
  // <select> value always matches an option (no React "value not in options"
  // warning). Messages carry no timestamp, so there's nothing finer to sort by:
  // we keep the store's own (first-message insertion) order.
  const chatOptions = useMemo(() => {
    const store = chats || {}
    const keys = Object.keys(store).filter(mk => (store[mk]?.length ?? 0) > 0)
    if (modelKey && !keys.includes(modelKey)) keys.push(modelKey)
    return keys.map(mk => {
      const msgs = store[mk] || []
      const m = models.find(x => (x.model_key ?? x.key) === mk)
      return {
        modelKey: mk,
        name: m?.name ?? mk,
        count: msgs.length,
        // "active" = still generating. The open model reports its live stream
        // flag; other threads fall back to a lingering in-flight `status` on a
        // message (provisioning/continuation) — the only streaming trace the
        // store keeps once real tokens start replacing it.
        active: (mk === modelKey && streaming) || msgs.some(x => x?.status),
      }
    })
  }, [chats, models, modelKey, streaming])

  useEffect(() => { inputRef.current?.focus(); setAllocation(null) }, [modelKey])
  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }) }, [messages])

  const onPickFile = useCallback(async (e) => {
    const file = e.target.files?.[0]
    e.target.value = ''
    if (!file) return
    const isImage = file.type.startsWith('image/')
    setAttachment({ name: file.name, isImage, uploading: true })
    try {
      if (isImage) {
        // Images ride inline as base64 in the chat request (payload.images) —
        // no /uploads round-trip, so vision works without an upload or its auth.
        const dataUrl = await readFileAsDataURL(file)
        setAttachment({ name: file.name, isImage, dataUrl })
      } else {
        // Non-image files still need a server path (their text is inlined
        // server-side via the file channel).
        const res = await uploadFile(file)
        setAttachment({ name: file.name, isImage, dataUrl: null, path: res.path })
      }
    } catch (err) {
      alert(`Could not attach file: ${err?.message ?? err}`)
      setAttachment(null)
    }
  }, [])

  const send = useCallback(async () => {
    const text = input.trim()
    const att = attachment
    if ((!text && !att) || streaming || att?.uploading) return
    setInput('')

    if (text === '/clear') { setMessages([]); return }
    if (text.startsWith('/system ')) { setSystem(text.slice(8).trim()); return }
    if (text.startsWith('/tokens ')) {
      const n = parseInt(text.slice(8).trim(), 10)
      if (!isNaN(n)) setMaxTokens(n)
      return
    }

    const userMsg = { role: 'user', content: text }
    if (att) userMsg.attachment = att
    const history = [...messages, userMsg]
    setMessages(history)
    setAttachment(null)
    setStreaming(true)
    setAllocation(null)   // cleared until this request's dispatch status arrives

    const wireMessages = history
      .filter(m => !m.error)                    // never replay failed turns as context
      .map(({ role, content, attachment: a }) => {
        const base = { role, content }
        // Per-message image/file fields aren't carried by the backend's message
        // schema; the current turn's image goes inline via payload.images and a
        // file via payload.file (set below).
        if (a?.path) base.file = a.path
        return base
      })
    // Prepend the active system prompt (set via /system) as a system turn so it
    // actually reaches the model — previously it was stored client-side but
    // never transmitted.
    if (system) wireMessages.unshift({ role: 'system', content: system })
    // Client-generated id so we can cancel this exact request; the server
    // echoes it back (and may override) via the 'request' SSE event.
    const reqId = (crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`)
    reqIdRef.current = reqId
    const payload = {
      model_key: modelKey,
      // Send the full conversation (incl. this turn) so the model has context;
      // the backend ChatRequest prefers `messages` over `prompt`. `prompt` is
      // kept as a fallback for any path that still reads the single-turn field.
      messages: wireMessages,
      prompt: text,
      request_id: reqId,
    }
    // Omit max_new_tokens entirely unless the user set one via /tokens — the
    // backend then defaults to the model's full context and auto-continues
    // past it, so responses are never truncated.
    if (maxTokens) payload.max_new_tokens = maxTokens
    if (att?.path) payload.file = att.path
    // The current turn's image rides inline as base64 (data URL) in payload.images;
    // the backend folds it into the latest user turn for the vision model. Without
    // this the image is read but never sent and the model is blind to it.
    if (att?.isImage && att?.dataUrl) payload.images = [att.dataUrl]
    const modelName = model?.name ?? modelKey
    setMessages(prev => [...prev, { role: 'assistant', content: '', model: modelName }])

    const ctrl = new AbortController()
    abortRef.current = ctrl
    try {
      const resp = await hugpyFetch('/api/chat/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: ctrl.signal,
      })
      if (!resp.ok) throw new Error(`${resp.status}: ${await resp.text()}`)

      const reader = resp.body.getReader()
      const dec = new TextDecoder()
      let buf = ''
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        buf += dec.decode(value, { stream: true })
        const lines = buf.split('\n')
        buf = lines.pop() ?? ''
        for (const line of lines) {
          if (!line.startsWith('data: ')) continue
          const raw = line.slice(6).trim()
          if (!raw || raw === '[DONE]') continue
          try {
            const evt = JSON.parse(raw)
            if (evt.type === 'request') {
              // Server's authoritative request_id for cancellation.
              if (evt.request_id) reqIdRef.current = evt.request_id
            } else if (evt.type === 'status' && evt.served_by != null) {
              // Allocation announcement — which worker (or local) is serving
              // this request. Drives the banner at the top of the chat box;
              // re-emitted as 'local' if the chosen worker falls back.
              setAllocation({
                servedBy: evt.served_by,
                workerId: evt.worker_id || '',
                workerName: evt.worker_name || (evt.served_by === 'local' ? 'local' : ''),
              })
            } else if (evt.type === 'status') {
              // Provisioning / continuation progress — show transiently on the
              // assistant bubble; cleared as soon as real tokens arrive.
              const pct = evt.progress != null ? ` ${Math.round(evt.progress * 100)}%` : ''
              setMessages(prev => {
                const copy = [...prev]
                const last = copy[copy.length - 1]
                if (last?.role === 'assistant') copy[copy.length - 1] = { ...last, status: `${evt.message || evt.stage || 'working'}${pct}` }
                return copy
              })
            } else if (evt.type === 'token') {
              setMessages(prev => {
                const copy = [...prev]
                const last = copy[copy.length - 1]
                if (last?.role === 'assistant') copy[copy.length - 1] = { ...last, content: last.content + evt.text, status: null }
                return copy
              })
            } else if (evt.type === 'error') {
              setMessages(prev => {
                const copy = [...prev]
                const last = copy[copy.length - 1]
                if (last?.role === 'assistant') copy[copy.length - 1] = { ...last, content: `[Error: ${evt.message}]`, error: true }
                return copy
              })
            }
          } catch { /* ignore */ }
        }
      }
    } catch (e) {
      if (e.name === 'AbortError') {
        // User stopped it — mark the partial as stopped, not an error.
        setMessages(prev => {
          const copy = [...prev]
          const last = copy[copy.length - 1]
          if (last?.role === 'assistant') {
            copy[copy.length - 1] = { ...last, status: null, content: last.content + ' ⏹', stopped: true }
          }
          return copy
        })
      } else {
        setMessages(prev => {
          const copy = [...prev]
          const last = copy[copy.length - 1]
          if (last?.role === 'assistant' && last.content === '') {
            copy[copy.length - 1] = { role: 'assistant', content: `[Error: ${e.message}]`, error: true }
          } else {
            copy.push({ role: 'assistant', content: `[Error: ${e.message}]`, error: true })
          }
          return copy
        })
      }
    } finally {
      setStreaming(false)
      abortRef.current = null
      reqIdRef.current = null
    }
  }, [input, attachment, messages, modelKey, system, maxTokens, streaming])

  // Stop the in-flight response: tell the worker to halt generation (so the GPU
  // stops doing work), then abort the local fetch.
  const stop = useCallback(() => {
    const rid = reqIdRef.current
    if (rid) {
      hugpyFetch(`/api/llm/chat/cancel/${encodeURIComponent(rid)}`, { method: 'POST' }).catch(() => {})
    }
    abortRef.current?.abort()
  }, [])

  const onKey = useCallback((e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() }
  }, [send])

  return (
    <aside className="chat-panel">
      <div className="chat-header">
        <div className="chat-title">
          <span className="chat-model">{model?.name ?? modelKey}</span>
          <span className="chat-meta">
            {model?.framework} · <span title={Array.isArray(model?.tasks) && model.tasks.length > 1 ? `all tasks: ${model.tasks.join(', ')}` : undefined}>{model?.primary_task ?? model?.task}</span>
            {system && <span className="system-set" title={system}> · sys</span>}
            {' · '}{maxTokens ? `max ${maxTokens} tok` : 'unbounded (auto-continue)'}
            {vlCapable && <span className="vl-tag" title="vision-language model"> · 🖼 VL</span>}
          </span>
        </div>
        <div className="chat-header-right">
          {/* Conversation switcher: jump the panel to any other model that has a
              populated (or currently active) chat. Only shown once there's
              somewhere to switch TO — a single-entry dropdown is just noise.
              Options are recomputed live from the shared store above, and
              picking one calls App's own chat-opener, so it lands identically to
              opening that model from the model list (history loads from the
              store on open, as it already does). */}
          {chatOptions.length > 1 && (
            <select
              className="chat-switcher"
              value={modelKey}
              onChange={(e) => { const mk = e.target.value; if (mk && mk !== modelKey) onSwitchChat?.(mk) }}
              title="Switch to another model's saved conversation"
            >
              {chatOptions.map(opt => (
                <option key={opt.modelKey} value={opt.modelKey}>
                  {opt.active ? '● ' : ''}{opt.name} · {opt.count} msg{opt.count === 1 ? '' : 's'}
                </option>
              ))}
            </select>
          )}
          <span
            className={`chat-status ${streaming ? 'is-streaming' : 'is-idle'}`}
            title={streaming ? 'Generating a response…' : 'Conversation saved locally — survives tab changes and reloads'}
          >
            {streaming
              ? '● generating…'
              : `● saved · ${messages.length} msg${messages.length === 1 ? '' : 's'}`}
          </span>
          <button className="btn-clear-chat" onClick={() => setMessages([])} title="Clear conversation" disabled={streaming}>✕ clear</button>
          <button className="btn-close" onClick={onClose} title="Close chat">✕</button>
        </div>
      </div>

      <div
        className={`chat-alloc ${allocation ? (allocation.servedBy === 'local' ? 'is-local' : 'is-worker') : 'is-pending'}`}
        title="The allocation that served the most recent request"
      >
        <span className="alloc-label">allocation</span>
        <span className="alloc-value">
          {!allocation
            ? '—'
            : allocation.servedBy === 'local'
              ? 'local (this node)'
              : `${allocation.workerName || allocation.workerId}${
                  allocation.workerId && allocation.workerId !== allocation.workerName
                    ? ` (${allocation.workerId})` : ''
                }`}
        </span>
      </div>

      <div className="chat-messages">
        {messages.length === 0 && (
          <div className="chat-empty">
            <p>Chat with <strong>{model?.name ?? modelKey}</strong></p>
            <p className="chat-hint">Commands: {PLACEHOLDER_CMDS}</p>
            <p className="chat-hint">Attach a file with 📎{vlCapable ? ' (images supported)' : ''}.</p>
          </div>
        )}
        {messages.map((msg, i) => (
          <div key={i} className={`msg msg-${msg.role} ${msg.error ? 'msg-error' : ''}`}>
            <span className="msg-role">
              {msg.role === 'assistant' ? (msg.model ?? 'assistant') : msg.role}
            </span>
            {msg.attachment?.isImage && msg.attachment.dataUrl && (
              <img className="msg-thumb" src={msg.attachment.dataUrl} alt={msg.attachment.name} title={msg.attachment.name} />
            )}
            {msg.attachment && !msg.attachment.isImage && (
              <span className="msg-file" title={msg.attachment.name}>📎 {msg.attachment.name}</span>
            )}
            {msg.status && !msg.content && (
              <div className="msg-status">⏳ {msg.status}</div>
            )}
            <pre className="msg-content">{msg.content}
              {msg.role === 'assistant' && streaming && i === messages.length - 1 && <span className="cursor">▌</span>}
            </pre>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      {attachment && (
        <div className="attach-strip">
          {attachment.isImage
            ? <img src={attachment.dataUrl} alt={attachment.name} className="attach-thumb" />
            : <span className="attach-file">📎</span>}
          <span className="attach-name" title={attachment.name}>
            {attachment.name}{attachment.uploading ? ' · uploading…' : ''}
          </span>
          <button className="attach-remove" onClick={() => setAttachment(null)} disabled={streaming} title="Remove attachment">×</button>
        </div>
      )}

      <div className="chat-input-row">
        <input ref={fileRef} type="file" style={{ display: 'none' }} onChange={onPickFile} />
        <button className="btn-attach" onClick={() => fileRef.current?.click()} disabled={streaming} title="Attach file">📎</button>
        <textarea
          ref={inputRef} className="chat-input" rows={3} value={input}
          onChange={e => setInput(e.target.value)} onKeyDown={onKey}
          placeholder="Message… (Enter to send, Shift+Enter for newline)" disabled={streaming}
        />
        {streaming ? (
          <button className="btn-stop" onClick={stop} title="Stop generating">
            ⏹ Stop
          </button>
        ) : (
          <button className="btn-send" onClick={send} disabled={(!input.trim() && !attachment) || attachment?.uploading}>
            ↑ Send
          </button>
        )}
      </div>
    </aside>
  )
}
