import { useState, useCallback, useEffect } from 'react'

// Per-model conversation store, persisted to localStorage so chats survive tab
// switches, route changes, and full page reloads. Keyed by modelKey:
//   { [modelKey]: Message[] }
// ChatPanel used to hold `messages` in local state, so it lost everything the
// moment it unmounted (any tab change) and bled one model's history into the
// next (no per-model isolation). Lifting + persisting here fixes both.

const KEY = 'hugpy.chats.v1'
const EMPTY = []   // stable reference so "no messages yet" doesn't churn effects

function load() {
  try { return JSON.parse(localStorage.getItem(KEY)) || {} } catch { return {} }
}

// Drop anything heavy or purely transient before persisting: base64 image
// dataUrls would blow the ~5MB localStorage quota, and `status`/cursor state is
// only meaningful mid-stream.
function sanitize(chats) {
  const out = {}
  for (const [modelKey, msgs] of Object.entries(chats)) {
    if (!Array.isArray(msgs) || msgs.length === 0) continue
    out[modelKey] = msgs.map(m => {
      const { status, ...rest } = m
      if (rest.attachment?.dataUrl) {
        rest.attachment = { ...rest.attachment, dataUrl: undefined }
      }
      return rest
    })
  }
  return out
}

export function useChats() {
  const [chats, setChats] = useState(load)   // { [modelKey]: Message[] }

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(sanitize(chats))) } catch { /* quota / private mode */ }
  }, [chats])

  const getMessages = useCallback((modelKey) => chats[modelKey] || EMPTY, [chats])

  // setMessages(modelKey, next | prev => next) — mirrors the React setState API
  // ChatPanel already uses, so its call sites need no rewrite.
  const setMessages = useCallback((modelKey, updater) => {
    setChats(prev => {
      const cur = prev[modelKey] || EMPTY
      const next = typeof updater === 'function' ? updater(cur) : updater
      return { ...prev, [modelKey]: next }
    })
  }, [])

  const clearChat = useCallback((modelKey) => {
    setChats(prev => {
      if (!(modelKey in prev)) return prev
      const copy = { ...prev }
      delete copy[modelKey]
      return copy
    })
  }, [])

  return { chats, getMessages, setMessages, clearChat }
}
